import { splitProps, type JSX } from 'solid-js';
import { getSpinnerSize, spinnerStyleKeys } from '../lib/core';
import type { SpinnerBaseProps } from '../lib/core';
import styles from './spinner.module.scss';
export interface SpinnerProps extends JSX.SvgSVGAttributes<SVGSVGElement>, SpinnerBaseProps {}
export function Spinner(props: SpinnerProps) {
	const [local, rest] = splitProps(props, ['class', 'size', 'children']);
	const size = () => getSpinnerSize(local.size ?? 'default');
	return (
		<svg
			{...rest}
			data-slot="spinner"
			role={rest.role ?? 'status'}
			aria-label={rest['aria-label'] ?? 'Loading'}
			data-size={size()}
			viewBox="0 0 24 24"
			fill="none"
			stroke="currentColor"
			stroke-width="2"
			stroke-linecap="round"
			stroke-linejoin="round"
			class={`${styles[spinnerStyleKeys.root]} ${local.class ?? ''}`}>
			<path d="M21 12a9 9 0 1 1-6.219-8.56" />
			{local.children}
		</svg>
	);
}
export default Spinner;

@use '../../../styles/variables/colors' as *;

// 旋转动画
@keyframes tile-spinner-rotate {
	from {
		transform: rotate(0deg);
	}

	to {
		transform: rotate(360deg);
	}
}

// Spinner 根元素（svg）
.root {
	flex-shrink: 0;
	color: var(--tile-spinner-color, $muted-foreground);
	animation: tile-spinner-rotate 0.8s linear infinite;

	// 尺寸
	&[data-size='sm'] {
		width: $spacing-4;
		height: $spacing-4;
	}

	&[data-size='default'] {
		width: var(--tile-spinner-size, $spacing-5);
		height: var(--tile-spinner-size, $spacing-5);
	}

	&[data-size='lg'] {
		width: $spacing-8;
		height: $spacing-8;
	}
}
